func ThemePalette(name string) Palette { return palettes[name] }
func (f *Frame) ThemeColor(c color.Color) color.Color {
	switch c {
	case Accent:
		return f.Palette.Accent
	case Dim:
		return f.Palette.Dim
	case Text:
		return f.Palette.Text
	case Subtle:
		return f.Palette.Subtle
	case Surface:
		return f.Palette.Surface
	case SurfDim:
		return f.Palette.SurfDim
	case Red:
		return f.Palette.Red
	case Green:
		return f.Palette.Green
	case Yellow:
		return f.Palette.Yellow
	case Mauve:
		return f.Palette.Mauve
	}
	return c
}
